using System;using System.Collections.Generic;using System.Globalization;using System.Reflection;using OpenMetaverse;using OpenSim.Framework;
partial class Rpc{partial void Pick(ref object data,string method,string uri,string id,ref bool? handled){if(data is UserProfilePick)handled=PickFixture.Rpc(ref data,method,uri,id);}}
partial class Grid{public int IsLocalGrid(string gate,bool resolve){F.Trace+="isgrid:"+F.T(gate)+":"+(resolve?1:0)+";";PickFixture.Fail(1,"isgrid");return PickFixture.Local;}}
class PickRegion{public int RegionLocX=>PickFixture.X;public int RegionLocY=>PickFixture.Y;public ulong RegionHandle=>((ulong)(uint)RegionLocX<<32)|(uint)RegionLocY;}
class PickRegionInfo{public UUID ScopeID{get{F.Trace+="scope;";PickFixture.Fail(16,"scope");return F.Id(8);}}}
class PickGridService{public PickRegion GetRegionByName(UUID scope,string name){F.Trace+="region:"+scope+":"+F.T(name)+";";PickFixture.Fail(32,"region");return (PickFixture.Seams&64)!=0?null:new PickRegion();}}
partial class World{public PickGridService GridService{get{F.Trace+="gridservice;";PickFixture.Fail(2,"gridservice");return (PickFixture.Seams&4)!=0?null:new PickGridService();}}public PickRegionInfo RegionInfo=>(PickFixture.Seams&8)!=0?null:new PickRegionInfo();}
class PickClient:PicksClient{public override void SendPickInfoReply(UUID pick,UUID creator,bool top,UUID parcel,string name,string desc,UUID snapshot,string user,string original,string sim,Vector3d position,int order,bool enabled){F.Trace+="pick:"+pick+":"+creator+":"+(top?1:0)+":"+parcel+":"+F.T(name)+":"+F.T(desc)+":"+snapshot+":"+F.T(user)+":"+F.T(original)+":"+F.T(sim)+":"+PickFixture.Vector(position)+":"+order+":"+(enabled?1:0)+";";if((PickFixture.Seams&256)!=0&&PickFixture.Last is UserProfilePick ad)ad.Name="callback";if((PickFixture.Seams&512)!=0){var again=PicksFixture.Current.GetPick(PickFixture.Target,PickFixture.Query);F.Trace+="again:"+PicksFixture.Identity(again)+":"+PickFixture.Dump(again)+";";}F.Fail(268435456,"pick");}}
static class PickFixture{
 public static int Seams,Local,X,Y;public static string Position,Gate;public static UUID Parcel,Target,Query;public static object Last;public static UserProfilePick Saved;
 public static void Fail(int mask,string message){if((Seams&mask)!=0)throw new Exception(message);}
 public static string Vector(Vector3d v)=>BitConverter.DoubleToUInt64Bits(v.X).ToString("x16")+":"+BitConverter.DoubleToUInt64Bits(v.Y).ToString("x16")+":"+BitConverter.DoubleToUInt64Bits(v.Z).ToString("x16");
 public static UserProfilePick Fill(UUID id)=>new UserProfilePick{PickId=id,CreatorId=F.Id(7),TopPick=true,Name=F.Text,OriginalName=F.Text,Desc=F.Text,ParcelId=Parcel,SnapshotId=F.Id(9),ParcelName=F.Text,SimName=F.Text,GlobalPos=Position,Gatekeeper=Gate,SortOrder=int.MinValue,Enabled=true};
 public static string Dump(object value){if(value==null)return "N";if(value is not UserProfilePick p)return "X";return p.PickId+":"+p.CreatorId+":"+(p.TopPick?1:0)+":"+F.T(p.Name)+":"+F.T(p.OriginalName)+":"+F.T(p.Desc)+":"+p.ParcelId+":"+p.SnapshotId+":"+F.T(p.ParcelName)+":"+F.T(p.SimName)+":"+F.T(p.GlobalPos)+":"+F.T(p.Gatekeeper)+":"+p.SortOrder+":"+(p.Enabled?1:0);}
 public static bool Rpc(ref object data,string method,string uri,string id){F.Trace+="pick-rpc:"+method+":"+F.T(uri)+":"+Dump(data)+":"+(UUID.TryParse(id,out var g)&&!g.IsZero()?1:0)+";";Last=data;if(F.Mode==7)throw new Exception("rpc");if(F.Mode==0)return false;if(F.Mode!=8){var filled=Fill(((UserProfilePick)data).PickId);if(F.Mode==3||F.Mode==4)filled.PickId=F.Id(4);if(F.Mode==10)filled.CreatorId=UUID.Zero;if(F.Mode==11)filled.SnapshotId=UUID.Zero;if(F.Mode==12)filled.GlobalPos="bad";if(F.Mode==13)filled.PickId=UUID.Zero;if(F.Mode==14)filled.ParcelId=UUID.Zero;if(F.Mode==15)filled.ParcelId=F.Id(5);if(F.Mode==16)filled.GlobalPos=null;if(F.Mode==17)filled.Gatekeeper=null;if(F.Mode==3||F.Mode==4)data=filled;else foreach(var field in typeof(UserProfilePick).GetFields())field.SetValue(data,field.GetValue(filled));}if(F.Mode==5||F.Mode==9)data=null;if(F.Mode==6)data=new UserPreferences();Last=data;return F.Mode!=2&&F.Mode!=4&&F.Mode!=9;}
 public static string State(Original m){string One(UUID key){m.Cache.TryGetValue(key,out var e);string count=m.Cache.Count.ToString();if(e==null)return count+":N";string identity=PicksFixture.Identity(e);string rows="";if(e.picks!=null)foreach(var row in e.picks){if(rows!="")rows+=",";rows+=row.Key+"="+PicksFixture.Identity(row.Value)+":"+Dump(row.Value);}return count+":"+identity+":"+e.flags+":"+F.T(e.born)+":"+PicksFixture.Dump(e.picksList)+":"+PicksFixture.Dump(e.classifiedsLists)+":"+(e.props==null?"N":e.props.UserId.ToString())+":"+(e.picks==null?"N":rows);}string a=One(Target),b=One(F.Id(2)),saved=PicksFixture.Identity(Saved),last=PicksFixture.Identity(Last);return a+";"+b+";"+saved+":"+Dump(Saved)+";"+last+":"+Dump(Last);}
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var p=line.Split(' ');F.Mode=int.Parse(p[0]);F.Flags=int.Parse(p[1]);Seams=int.Parse(p[2]);Local=int.Parse(p[3]);X=int.Parse(p[4]);Y=int.Parse(p[5]);F.Uri=PicksFixture.Decode(p[6]);string target=PicksFixture.Decode(p[7]),query=PicksFixture.Decode(p[8]);UUID.TryParse(target,out Target);UUID.TryParse(query,out Query);F.Text=PicksFixture.Decode(p[9]);Position=PicksFixture.Decode(p[10]);Gate=PicksFixture.Decode(p[11]);F.AssetUri=PicksFixture.Decode(p[12]);UUID.TryParse(PicksFixture.Decode(p[13]),out Parcel);F.Trace="";Last=null;Saved=null;PicksFixture.Reset();var m=new Original();PicksFixture.Current=m;IClientAPI client=(F.Flags&1)!=0?null:new PickClient();var output=new List<string>();foreach(var token in p[14..]){string result="OK";try{if(token[0]=='t')PicksFixture.Now=double.Parse(token[1..],CultureInfo.InvariantCulture);else if(token[0]=='m')F.Mode=int.Parse(token[1..]);else switch(token){case "R":List<string> args=(F.Flags&4)!=0?null:(F.Flags&8)!=0?new():(F.Flags&2097152)!=0?new(){target}:new(){target,query};m.PickInfoRequest((F.Flags&2)!=0?new object():client,"ignored",args);break;case "G":Saved=m.GetPick(Target,Query);break;case "H":Saved=m.GetPick(Target,F.Id(4));break;case "M":Saved.Name="mutated";Saved.GlobalPos=Position;Saved.ParcelId=Parcel;break;case "C":m.Cache.Clear();break;case "P":m.Cache.GetType().GetMethod("Purge",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(m.Cache,new object[]{null});break;case "S":m.Cache.AddOrUpdate(Target,null,300.0);break;default:var e=new UserProfileCacheEntry{flags=55,born="seed",picksList=new Dictionary<UUID,string>{{F.Id(7),"other"}},classifiedsLists=new Dictionary<UUID,string>{{F.Id(9),"ad"}},props=new UserProfileProperties{UserId=F.Id(7)},picks=new()};var seed=Fill(Query);if(token=="D")seed.GlobalPos="bad";if(token!="W")e.picks[Query]=token=="E"?null:seed;m.Cache.AddOrUpdate(token=="B"?F.Id(2):Target,e,300.0);break;}}catch(Exception error){if(error is TargetInvocationException&&error.InnerException!=null)error=error.InnerException;result="EX:"+F.H(error.Message);}output.Add(result+":"+State(m));}Console.WriteLine(string.Join('/',output)+"|"+F.H(F.Trace));}}
}
